-- CAB-0008: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin if exists(select 1 from public.entities where slug='pdp' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='gabungan-parti-sarawak'))) then raise exception 'CAB-0008: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party', parent.id,'pdp','Progressive Democratic Party','PDP','government','A component party of Gabungan Parti Sarawak (GPS).','2026-11-09','[{"label": "SPR · registered party symbols", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}, {"label": "PDP · 2026 party meeting", "url": "https://www.bernama.com/bm/news.php?id=2557971"}]'::jsonb from public.entities parent where parent.slug='gabungan-parti-sarawak' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='pdp' and type='party') then raise exception 'CAB-0008: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0008: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='gabungan-parti-sarawak' and type='alliance') then raise exception 'CAB-0008: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('tiong-king-sing','fahmi-fadzil') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0008: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('bintulu','lembah pantai') and slug not in ('tiong-king-sing','fahmi-fadzil')) then raise exception 'CAB-0008: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0008:%' and (m.source_type <> 'editorial' or e.slug not in ('tiong-king-sing','fahmi-fadzil') or m.import_key not like 'CAB-0008:' || e.slug || ':%')) then raise exception 'CAB-0008: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'tiong-king-sing','Tiong King Sing','government','Minister of Tourism, Arts and Culture','Bintulu','Sarawak','Tiong King Sing is Minister of Tourism, Arts and Culture. He represents Bintulu, Sarawak, in the Dewan Rakyat. He is a member of the Progressive Democratic Party (PDP).','https://www.motac.gov.my/','/portraits/tiong-king-sing.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P217.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Bintulu", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4256"}, {"label": "PDP · 2026 party meeting", "url": "https://www.bernama.com/bm/news.php?id=2557971"}]'::jsonb from public.entities parent where parent.slug='pdp' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'fahmi-fadzil','Fahmi Fadzil','government','Minister of Communications','Lembah Pantai','Kuala Lumpur','Fahmi Fadzil is Minister of Communications. He represents Lembah Pantai, Kuala Lumpur, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://www.komunikasi.gov.my/','/portraits/fahmi-fadzil.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/yb%20Fahmi.jpeg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Lembah Pantai", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4160"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('tiong-king-sing','fahmi-fadzil') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0008: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0008:tiong-king-sing:vm2026-47m-visitors','Attract 47 million visitors during Visit Malaysia 2026','Economy',null,null,'2026-12-31','2026-02-11','https://www.motac.gov.my/en/galeri-aktiviti/ucapan-ybm-dato-seri-tiong-king-sing-di-majlis-peluncuran-kempen-mesra-malaysia-2026/',null,null,'MOTAC’s account of Tiong’s Mesra Malaysia campaign launch states a target of 47 million visitors for Visit Malaysia 2026.','The campaign launch is confirmed, but the comparable full-year visitor result was not established. Visitors and overnight tourists are different measures; no tourist-arrivals figure is substituted. Target outcome and completion percentage remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='tiong-king-sing' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0008:fahmi-fadzil:internet-populated-areas','Extend Internet coverage to all populated areas','Digital','in_progress',null,null,'2026-10-26','https://www.bernama.com/en/general/news.php?id=2626023','2026-10-27','https://www.bernama.com/en/general/news.php?id=2626023','Fahmi said JENDELA would use satellite and small-cell solutions to reach 100% Internet coverage in populated areas, including remote settlements.','The 27 October report gives a 99% coverage baseline and describes the planned technology changes. Coverage is a sector metric, not a completion score. This is an ongoing expansion; the source supplies no firm overall deadline.','2026-11-09','editorial',false from public.entities e where e.slug='fahmi-fadzil' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

